import { useState } from "react";
import { useNavigate } from "react-router-dom";

function Issue_request({ projects, setIssues }) {

    const navigate = useNavigate();
    const [selectedProject, setSelectedProject] = useState("");
    const [newIssue, setNewIssue] = useState("");
    const [description, setDescription] = useState("");
    const [reporter, setReporter] = useState("");

    const handleAddIssue = () => {
        if (selectedProject === "") {
            alert("프로젝트를 선택해주세요.");
            return;
        }

        if (newIssue.trim() === "") {
            alert("이슈 제목을 입력해주세요.");
            return;
        }

        if (description.trim() === "") {
            alert("이슈 내용을 입력해주세요.");
            return;
        }

        if (reporter.trim() === "") {
            alert("이슈 건의자 이름을 입력해주세요.");
            return;
        }

        const project = projects.find(
            (item) => String(item.id) === selectedProject
        );

        const issue = {
            id: Date.now(),
            projectId: Number(selectedProject),
            projectName: project?.name || "-",
            customerName: project?.customerName || "-",
            title: newIssue.trim(),
            description: description.trim(),
            reporterName: reporter.trim(),
            status: "접수",
            createdAt: new Date().toLocaleDateString("sv-SE")
        };

        setIssues((previousIssues) => [...previousIssues, issue]);
        navigate(`/issue/${issue.id}`);
    };

    return (
        <main className="issue-page">
            <section className="issue-register">
                <h3>새로운 이슈 등록</h3>

                <div className="issue-register-form">
                    {/* 프로젝트 선택 */}
                    <select
                        value={selectedProject}
                        onChange={(e) => setSelectedProject(e.target.value)}
                    >
                        <option value="">프로젝트를 선택해주세요</option>
                        {projects.map((project) => (
                            <option key={project.id} value={project.id}>
                                {project.id} - {project.name}
                            </option>
                        ))}
                    </select>

                    {/* 이슈 제목 */}
                    <input
                        type="text"
                        placeholder="새 이슈 제목을 입력하세요"
                        value={newIssue}
                        onChange={(e) => setNewIssue(e.target.value)}
                    />

                    {/* 이슈 내용 */}
                    <textarea
                        placeholder="이슈 발생 내용 및 오류 상황을 입력하세요"
                        value={description}
                        onChange={(e) => setDescription(e.target.value)}
                        rows="5"
                    />

                    {/* 이슈 건의자 */}
                    <input
                        type="text"
                        placeholder="이슈 건의자 이름"
                        value={reporter}
                        onChange={(e) => setReporter(e.target.value)}
                    />

                    <button onClick={handleAddIssue}>
                        + 이슈 등록
                    </button>

                    <button onClick={() => navigate("/issue")}>
                        목록으로 돌아가기
                    </button>
                </div>
            </section>
        </main>
    );

}

export default Issue_request;
